-- 📚 꼭집 주거 사전 — 통합공공임대 소득 기준 가구원수 표(1인 170% · 2인 160% · 3인 이상 150% · 기준 중위소득) · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값 「통합공공임대」.
-- t3 = 정책 문장에 1인…170% · 2인…160% · 3인 이상…150% 셋 다 · ko = 「고령자복지」 낱말이 있는 공고 · tier = 임대료 구간 문장(「150% 초과 170% 이하」 — 소득 기준이 아니라 임대료 6구간 · 사전 문장에 섞지 않는다).
-- 🔵 2026-11-09(조사 「사전 5차 후보 둘」 1-ⓑ 초안 · 판정 「고령자복지 한정 아님 — 이름 넓힘」 · 우편함 「코드·운영 — 📚 사전 SQL 새 둘 + 개정 둘 …」 1).
-- 확인 2026-11-09 · 실행 약 3초(관리 API 왕복) · 결과:
-- {"anns": 11, "t3": 10, "t3_ko": 3, "only_1in": 1, "none": 0, "tier": 10, "pri120": 1, "t3_ex": ["21442_1_제주특별자치도_서귀포시", "20857_1_제주특별자치도_서귀포시", "2015122300020993", "2015122300020992"], "other_ex": ["2015122300020627"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t from announcement_policies p join a using(announcement_id) where a.yr=2026 and a.std='통합공공임대'),f as(select announcement_id,bool_or(t~'1인.{0,50}170\s*%')a1,bool_or(t~'2인.{0,50}160\s*%')a2,bool_or(t~'3인\s*이상.{0,50}150\s*%')a3,bool_or(t~'고령자\s*복지')ko,bool_or(t~'150\s*%\s*초과\s*170\s*%')tier,bool_or(t~'우선\s*공급\s*120\s*%')pri from y group by 1)select json_build_object('anns',(select count(*) from f),'t3',(select count(*) from f where a1 and a2 and a3),'t3_ko',(select count(*) from f where a1 and a2 and a3 and ko),'only_1in',(select count(*) from f where a1 and not(a2 and a3)),'none',(select count(*) from f where not a1),'tier',(select count(*) from f where tier),'pri120',(select count(*) from f where pri),'t3_ex',(select json_agg(i) from(select announcement_id i from f where a1 and a2 and a3 order by 1 desc limit 4)q),'other_ex',(select json_agg(i) from(select announcement_id i from f where not(a1 and a2 and a3) order by 1)q))j;
